"""离线审核页；在已打包的 review 目录运行，不包含模型推理。"""
import argparse
from pathlib import Path
import json

p=argparse.ArgumentParser();p.add_argument('directory');args=p.parse_args()
root=Path(args.directory);root.mkdir(parents=True,exist_ok=True)
scenes=[dict(name='scene_0230',actor=22,cam=5,start=18,end=47,coverage='0.000426%',observed='2 / 469,403',blocked=21,prior=18,neighbor='430 / 1,279,616（0.034%）',title='车没有变成干净背景，而是变成灰块与车形',description='黄框锁定停车区的 actor22。只做 DELETE，不执行前后平移；此前 MOVE 的碰撞问题不参与本轮。新版早段可见灰色立面与深色阴影，后段仍出现棕黑色车形。灰块就是模型实际输出，不是审核页盖上的 mask。',watch='f18：灰色块状结构；f25：拉长的深色轮廓；f33 / f47：车形再次明显。检测器只拦截 f27–47，早段灰块漏检也不能通过。'),dict(name='scene_0255',actor=25,cam=3,start=65,end=94,coverage='0.27238%',observed='735 / 269,840',blocked=30,prior=27,neighbor='2,862 / 861,732（0.332%）',title='围栏与邻车更受保护，但 SUV 轮廓仍在',description='黄框锁定前景围栏后面的 actor25。青色保护范围锁住围栏与邻车；孔洞中可见的目标仍必须删掉。新版保留了更多原像素，但银灰色车体轮廓、涂抹和不自然条带仍然存在，不能当作 actor-free background。',watch='f65 / f72 / f80 / f94：对照原 SUV 的位置，检查围栏孔洞后面的银灰车形。不要把前景围栏保留下来误当成目标车已删除。')]

def video(s,key,title,caption,main=False):
    extra=f' data-full="{key}" data-zoom="{("original" if key=="target" else key)}_zoom"' if main else ''
    return f'''<figure><figcaption><b>{title}</b><span>{caption}</span></figcaption><video controls muted playsinline preload="metadata" poster="{s}/{key}_poster.jpg" src="{s}/{key}.mp4"{extra}></video><a class="download" href="{s}/{key}.mp4">单独打开视频 ↗</a></figure>'''

sections=[]
for s in scenes:
    n=s['name'];a=s['actor']
    cards=video(n,'target','① 原视频 · 目标高亮',f'actor{a}；黄框用于指出目标，不是删除 mask。',True)+video(n,'baseline','② 旧版 DriveEditor FULL','同相机、同帧范围；旧版已知失败，作为历史对照。',True)+video(n,'final','③ 新版 Hybrid + DiffuEraser','真实补景结果；保护与已观测像素已精确写回。',True)
    stages=video(n,'masks','三 mask：哪些像素允许改','黄＝delete；蓝＝额外生成上下文；青＝protect。')+video(n,'evidence_map','真实证据：实际填到了哪里','绿＝已接受真实像素；粉＝仍需生成的范围。')+video(n,'prior','DiffuEraser 内部 prior','原生低分辨率 prior 放大展示，已有涂抹/车形。')
    special='<p class="warning"><b>自动化例外：</b>本例原 SAM2 保护 mask 把围栏孔洞也涂实。助手查看首帧后给了 14 个 SAM2 点提示并选取镂空候选，再用有界相似变换跟踪。这个结果含人工式图像提示，不是全自动。实心 mask、退化 homography 和最终修正均已保留。</p>' if n=='scene_0255' else ''
    sections.append(f'''<section id="{n}" data-start="{s['start']}" data-scene="{n}">
<div class="section-title"><div><div class="eyebrow">CAM{s['cam']} · actor{a} · 源帧 {s['start']}–{s['end']}</div><h2>{n} — {s['title']}</h2></div><strong class="badge">未准入 Ω</strong></div>
<p>{s['description']}</p>{special}
<div class="controls"><button data-action="play">同步播放</button><button data-action="pause">暂停</button><button data-action="prev">← 上一帧</button><button data-action="next">下一帧 →</button><button data-action="zoom" aria-pressed="false">放大目标（三栏）</button><label>速度 <select><option value="0.5">0.5×</option><option value="1" selected>1×</option></select></label><output>源帧 f{s['start']} · 窗口 0.0s</output><input class="timeline" type="range" min="0" max="29" step="1" value="0" aria-label="{n} 视频帧"></div>
<div class="grid main-videos">{cards}</div>
<p class="watch"><b>怎么看：</b>{s['watch']} <span class="frame-links">快速定位 {' '.join(f'<button data-frame="{k}">f{s["start"]+k}</button>' for k in [0,7,15,29])}</span></p>
<div class="stats"><div><strong>{s['coverage']}</strong><span>delete 范围的真实证据覆盖<br>{s['observed']} 像素·帧</span></div><div><strong>{s['blocked']} / 30</strong><span>新版触发车辆再生 guard<br>内部 prior 为 {s['prior']} / 30</span></div><div><strong>0</strong><span>最终 PNG 的 protect 变化像素<br>只保证选中的保护范围</span></div></div>
<h3>展开中间环节：mask → 证据 → prior</h3><div class="grid diagnostics">{stages}</div>
<p>这些中间视频跟随上方同步播放与逐帧按钮。证据图中几乎看不到绿色是实际低覆盖结果，不是遗漏渲染。<a href="{n}/evidence.mp4">证据写入后的输入视频</a>里，残洞尚保留原车，不能当成完成的 DELETE；模型读取时才按 residual mask 遮掉它。<a href="{n}/native.mp4">DiffuEraser 原生整帧输出</a>保留用于区分模型与外部合成的影响。</p>
<p>独立重新检测的原邻车 mask 中，新版变化像素为 <b>{s['neighbor']}</b>。分母是当前检测出的邻车区域，非完整真值；不能由 protect 不变推导所有邻车绝对保真。prior 因分辨率变化不参与这一像素保持率比较。</p>
<details><summary>关键帧与逐项证据（点击展开）</summary><a href="{n}/quicklook_zoom.jpg"><img class="sheet" src="{n}/quicklook_zoom.jpg" alt="原视频、旧版、内部prior、新版的四时刻目标区域对照" loading="lazy"></a><p>四列依次为原视频 / 旧 DriveEditor / 内部 prior / 新版；四行对应本页快速定位的四个时刻。</p><div class="links"><a href="{n}/mask_stats.json">逐帧 mask</a><a href="{n}/evidence_stats.json">证据覆盖</a><a href="{n}/temporal_pair_audit.json">候选配准及拒绝原因</a><a href="{n}/mask_review.jpg">最终 mask 接触表</a></div></details>
</section>''')

html='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>v77 · Hybrid DELETE 两场景实测</title><style>
:root{color-scheme:dark;--bg:#0b111b;--panel:#121e2d;--line:#2c3d51;--muted:#aebed1;--text:#e9f0f9;--cyan:#79def2;--red:#ffb6b1}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.7 system-ui,"Microsoft YaHei",sans-serif}main{max-width:1680px;margin:auto;padding:35px 28px 70px}h1{font-size:34px;line-height:1.3;margin:12px 0}h2{font-size:24px;margin:8px 0}h3{margin:26px 0 12px}a{color:var(--cyan)}p{max-width:1300px}.eyebrow{font-size:13px;color:var(--cyan);letter-spacing:.04em}.muted{color:var(--muted)}.lead{font-size:19px}.badge{display:inline-block;padding:5px 11px;background:#442129;color:var(--red);border-radius:7px;white-space:nowrap}.notice,.warning,.watch{background:#1d2838;border-left:3px solid #edb964;padding:14px 18px}.warning{background:#30291e}.watch{font-size:15px;border-color:var(--cyan)}nav{display:flex;gap:18px;flex-wrap:wrap;margin:23px 0}section{border-top:1px solid var(--line);padding-top:34px;margin-top:35px}.section-title{display:flex;justify-content:space-between;gap:25px;align-items:center}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}figure{margin:0;background:var(--panel);border:1px solid var(--line);border-radius:10px;overflow:hidden}figcaption{padding:12px;min-height:92px}figcaption b{display:block}figcaption span{display:block;font-size:13px;color:var(--muted);margin-top:3px}video{display:block;background:#05080d;width:100%;aspect-ratio:960/536}.download{display:block;padding:4px 12px 8px;font-size:12px}.controls{display:flex;flex-wrap:wrap;align-items:center;gap:9px;margin:20px 0 13px}button,select{font:inherit;font-size:14px;color:var(--text);background:#22364d;border:1px solid #476681;border-radius:6px;padding:6px 10px;cursor:pointer}button:hover{background:#355775}button[aria-pressed="true"]{background:#225e67}output{color:var(--cyan);margin-left:auto;font-variant-numeric:tabular-nums}.timeline{width:100%;accent-color:var(--cyan)}.frame-links{display:block;margin-top:10px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:24px 0}.stats>div{background:#142335;padding:16px;border-radius:9px}.stats strong{font-size:29px;display:block}.stats span{font-size:14px;color:var(--muted)}.architecture{display:flex;flex-wrap:wrap;gap:10px;align-items:stretch;margin:20px 0}.component{flex:1;min-width:150px;border:1px solid #45627d;border-radius:8px;padding:13px;background:#132a3b;text-align:center}.component small{display:block;color:var(--muted)}.arrow{align-self:center;color:var(--cyan);font-size:25px}.gate{background:#3e222b;border-color:#b46e73}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:11px 14px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top}th{color:var(--cyan);background:var(--panel)}code{word-break:break-word;color:#c6ddea}.links{display:flex;gap:16px;flex-wrap:wrap}.sheet{max-width:100%;display:block;margin-top:15px}details{border:1px solid var(--line);padding:13px 17px;margin-top:15px;border-radius:8px}summary{cursor:pointer;color:var(--cyan)}footer{color:var(--muted);margin-top:30px;font-size:13px}@media(max-width:850px){main{padding:22px 15px}.grid{grid-template-columns:1fr}.stats{grid-template-columns:1fr}.section-title{display:block}h1{font-size:27px}output{margin-left:0}}
</style></head><body><main><div class="eyebrow">V77 / BACKGROUND BUILDER / 实际推理结果 · 2026-09-27</div><h1>三 mask + 真实证据 + DiffuEraser<br>两例仍未得到可准入的 DELETE 背景</h1><p class="lead">新生成结果已全部放在下面。保护区保持成立，但 scene_0230 仍有灰块和再生车形，scene_0255 仍有 SUV 残影。本候选已停止，未送入 Ω，旧 DriveEditor 默认与全部对照保留。</p><div class="notice"><b>本页是生成后的实测，不是下载准备页。</b>两例各一次 30 帧、10 Hz、3 秒推理；seed 42，官方 PCM 2-Step，960×536。原始 PNG 是像素验证依据；MP4 为人眼审核压缩版。工程准入判断为失败，<b>人工 verdict 仍待用户填写</b>。</div><nav><a href="#scene_0230">0230 · 再生车</a><a href="#scene_0255">0255 · 围栏后残影</a><a href="#method">方法与边界</a><a href="../v77-delete-full/index.html">旧完整 DELETE</a><a href="../v77-delete-repair/two-fixes.html">上一轮两项修复</a></nav>
<div class="architecture" aria-label="架构组件图"><div class="component">原 RGB + 目标轨迹<small>两个固定开发 scene</small></div><span class="arrow">→</span><div class="component">SAM2.1 多对象<small>delete / generate / protect</small></div><span class="arrow">→</span><div class="component">真实证据优先<small>LK / RANSAC + 原 Ω 重投影</small></div><span class="arrow">→</span><div class="component">残洞补景<small>内部 prior → DiffuEraser</small></div><span class="arrow">→</span><div class="component">保护与证据写回<small>保留原图不应改的区域</small></div><span class="arrow">→</span><div class="component gate">语义检查：拒绝<small>车辆再生 / 残影 → 不进入 Ω</small></div></div>
'''+''.join(sections)+'''
<section id="method"><h2>这轮具体改了什么，结果能说明什么</h2><table><thead><tr><th>环节</th><th>实际实现 / 证据</th><th>限制</th></tr></thead><tbody>
<tr><td>指令与目标</td><td>GT track 核对两例各 30 帧；只 DELETE，不新增占据体积。</td><td>不主张完整道路规则合法；未执行 MOVE，也未修复旧 MOVE。</td></tr>
<tr><td>三 mask</td><td>SAM2 多对象传播；delete 3px 边缘扩张；generate 再扩 16px 且排除 protect。</td><td>三个 mask 是外部工程控制，官方网络实际接收 residual_generate；0255 首帧围栏含助手点提示。</td></tr>
<tr><td>时序证据</td><td>原 RGB、LK 双向检查、局部 RANSAC；限制在 inlier 支持范围，双 donor 相隔至少 5 帧且 RGB 一致。</td><td>仅查目标有 GT 标注的帧，最大偏移3.6秒，未查轨迹消失后的帧。0230只接受2像素·帧，不能证明背景从未拍到。</td></tr>
<tr><td>几何证据</td><td>复用上一轮原 RGB 的 Ω / GT / LiDAR donor；地面延伸 actor 排除、≤20cm LiDAR 支持、双时刻深度/RGB一致。</td><td>0255 删除区只接受 735 像素·帧。它是经筛选的重投影支持，不是已知完整背景 GT。</td></tr>
<tr><td>生成</td><td>DiffuEraser 官方模型；其内部 ProPainter prior 单独存档；原生网络与采样不改，仅适配无损输入/输出及 mask。</td><td>没有重开独立 ProPainter 路线。prior 已有残影与最终车形并存，但未证明 prior 是唯一原因。</td></tr>
<tr><td>检查</td><td>60 帧像素/来源合同通过；新结果被 guard 拦截 21/30 与 30/30。原车正控制各 30/30 命中，空路面负控制无命中。</td><td>检测器会漏灰白块；这不是“删除成功率”。邻车保持指标限于检测出的像素范围，无隐藏背景真值。</td></tr>
<tr><td>旧 / 新对照</td><td>同窗口和显示尺寸，完整保留原视频、旧结果和新结果。</td><td>模型、mask、上下文及分块历史均有变化，不能把差异归因到单一模块。没有新场景泛化或跨相机成功证据。</td></tr>
</tbody></table><p class="muted">交付核验：24条本地视频共720帧解码通过，页面引用及JS语法通过。浏览器工具因本地file URL安全策略拦截预览，未完成浏览器交互实测；未绕过限制。</p>
<h3>为什么现在停</h3><p>按本轮 stop rule，三 mask + evidence-first + DiffuEraser 仍有目标车形残留，就停止继续叠加成熟补景模型。本轮未达到“两例都明显优于旧版”的继续条件；不再换 seed、放宽 guard 或添加生成器来凑通过。旧版本也有已知缺陷，保留它作为可复核默认不代表旧版合格。这个结果没有否定 GLB，也没有证明整个 background + explicit assets 表示不可行。</p>
<p>若后续进入数据路线，应先验证“真实干净视频遮挡监督 / 车辆移开后可可靠配准的背景监督”是否足够，而不是把当前生成结果当 GT。跨 scene 划分；重投影监督只在有支持的可见区域计损失。此页没有启动新训练。</p>
<h3>来源、资源与可复核文件</h3><p><code>WS-V77-HYBRID-BG-20260927/r2</code> · 远端 <code>/root/autodl-tmp/runs/worldsim_v77/WS-V77-HYBRID-BG-20260927/r2</code>。RTX 3090 24GB 串行推理；内部 prior + 两例 diffusion 共约 111 秒。PyTorch peak allocated 约 10.22 GiB，但运行中 GPU reserved 接近 24GB，不能据此声称只需 10GB 显存。0 训练、0 新 Ω 前向、0 新 GLB。</p>
<div class="links"><a href="registration.json">实验登记</a><a href="execution_notes.json">工程修正与手工提示</a><a href="evidence_summary.json">真实证据汇总</a><a href="generation_state.json">模型执行记录</a><a href="guard_summary.json">再生检查</a><a href="validation.json">60 帧合同验证</a><a href="background_admission.json">Ω 准入拒绝</a><a href="video_validation.json">24 视频解码核验</a><a href="report.md">完整技术报告</a></div><p>官方来源：<a href="https://github.com/lixiaowen-xw/DiffuEraser">DiffuEraser</a>；<a href="https://github.com/facebookresearch/sam2">SAM2</a>。本页的质量判断基于实际本地输出，非引用官方效果宣称。</p></section><footer>原 PNG、失败尝试、mask、来源记录和对照均保留。human_verdict = null。点击视频右下角可全屏检查细节。</footer></main>
<script>
document.querySelectorAll('section[data-scene]').forEach(section=>{
 const videos=[...section.querySelectorAll('video')],main=videos[0],slider=section.querySelector('.timeline'),out=section.querySelector('output'),start=Number(section.dataset.start);let playing=false,zoom=false,busy=false;
 const label=i=>{slider.value=i;out.textContent=`源帧 f${start+i} · 窗口 ${(i/10).toFixed(1)}s`;};
 const pause=()=>{playing=false;videos.forEach(v=>v.pause());};
 const seek=i=>{pause();i=Math.max(0,Math.min(29,i));videos.forEach(v=>{if(v.readyState>=1)v.currentTime=i/10+.002;else v.addEventListener('loadedmetadata',()=>v.currentTime=i/10+.002,{once:true});});label(i);};
 const play=async()=>{if(busy)return;document.querySelectorAll('section[data-scene]').forEach(x=>{if(x!==section)x.querySelector('[data-action="pause"]').click();});if(main.ended||main.currentTime>=2.99)seek(0);const t=main.currentTime;videos.forEach(v=>{if(v.readyState>=1)v.currentTime=t;});playing=true;const r=await Promise.allSettled(videos.map(v=>v.play()));if(r.some(x=>x.status==='rejected')){pause();out.textContent='视频加载/播放失败，请单独打开视频检查';}};
 section.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.frame!==undefined){seek(Number(b.dataset.frame));return;}switch(b.dataset.action){case 'play':await play();break;case 'pause':pause();break;case 'prev':seek(Number(slider.value)-1);break;case 'next':seek(Number(slider.value)+1);break;case 'zoom':{pause();busy=true;const i=Number(slider.value);zoom=!zoom;b.setAttribute('aria-pressed',String(zoom));b.textContent=zoom?'恢复全景（三栏）':'放大目标（三栏）';await Promise.all(videos.filter(v=>v.dataset.full).map(v=>new Promise(resolve=>{const done=()=>{v.currentTime=i/10+.002;resolve();};v.addEventListener('loadedmetadata',done,{once:true});v.addEventListener('error',resolve,{once:true});v.src=`${section.dataset.scene}/${zoom?v.dataset.zoom:v.dataset.full}.mp4`;v.load();})));busy=false;label(i);break;}}});
 slider.addEventListener('input',()=>seek(Number(slider.value)));section.querySelector('select').addEventListener('change',e=>videos.forEach(v=>v.playbackRate=Number(e.target.value)));
 main.addEventListener('timeupdate',()=>{label(Math.min(29,Math.floor((main.currentTime+.001)*10)));if(playing)videos.slice(1).forEach(v=>{if(v.readyState>=2&&Math.abs(v.currentTime-main.currentTime)>.08)v.currentTime=main.currentTime;});});main.addEventListener('ended',pause);main.addEventListener('pause',()=>{if(playing)pause();});
});
</script></body></html>'''
(root/'index.html').write_text(html,encoding='utf-8')
print(root/'index.html')
